from pathlib import Path
import xml.etree.ElementTree as ET
import base64,json
p=Path(__file__).parent;r=p.parent;ref=r/'refs-spritecollab';work=r/'Base-Tsareena-Mega';root=ET.parse(ref/'AnimData.xml').getroot();anims={}
for a in root.find('Anims'):
 name=a.findtext('Name');copy=a.findtext('CopyOf');anims[name]={'copy':copy,'index':int(a.findtext('Index'))}
 if copy:continue
 from PIL import Image
 im=Image.open(ref/(name+'-Anim.png'));w=int(a.findtext('FrameWidth'));h=int(a.findtext('FrameHeight'));anims[name].update(w=w,h=h,rows=im.height//h,durations=[int(x.text) for x in a.findall('Durations/Duration')],url='data:image/png;base64,'+base64.b64encode((ref/(name+'-Anim.png')).read_bytes()).decode())
 assert im.width==w*len(anims[name]['durations']) and im.height in (h,8*h)
for name,a in anims.items():
 if a['copy']:
  copy=a['copy'];a.update({k:v for k,v in anims[copy].items() if k not in ('copy','index')})
mega='data:image/png;base64,'+base64.b64encode((work/'Walk-Anim-avant-droite-PARTIEL.png').read_bytes()).decode()
html='''<!doctype html><html lang="fr"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Méga-Tsareena · aperçu actuel</title><style>body{background:#14221b;color:#edf5e9;margin:0;font:16px system-ui}main{max-width:1060px;margin:auto;padding:24px}h1{font-size:30px;margin:.3em 0}.note{background:#493d26;border-left:4px solid #ebc37a;line-height:1.5;padding:15px}.bar{display:flex;gap:12px;align-items:center;flex-wrap:wrap;margin:18px 0}button,select{font:inherit;border:0;border-radius:7px;padding:10px;background:#dfefd8;color:#19271e}.grid{display:grid;grid-template-columns:1fr 1fr;gap:14px}.card{background:#293c30;padding:14px;border-radius:10px}canvas{width:100%;height:300px;background:#cbdbc0;image-rendering:pixelated}h2{font-size:18px}a{color:#d5ffc6}.tag{font-size:14px;color:#cbd9ca}p{line-height:1.5}@media(max-width:700px){.grid{grid-template-columns:1fr}}</style><main><h1>Méga-Tsareena · aperçu actuel</h1><p class="note">Toutes les animations ci-dessous sont visibles pour <strong>Tsareena normale</strong>, comme référence SpriteCollab. Méga : <strong>4 images de marche provisoires sur 32, avant-droite uniquement</strong>, aucune autre animation n’est terminée. Le corps et les jambes sont issus du sprite normal ; la robe, la couronne et les cils sont ajoutés par retouche. Essai à vérifier, pas une animation finalisée. Les cases absentes sont indiquées, jamais remplacées silencieusement.</p><div class="bar"><label>Animation <select id="anim"></select></label><label>Direction <select id="dir"><option value="0">Face</option><option value="1" selected>Avant-droite</option><option value="2">Droite</option><option value="3">Arrière-droite</option><option value="4">Dos</option><option value="5">Arrière-gauche</option><option value="6">Gauche</option><option value="7">Avant-gauche</option></select></label><button id="play">Pause</button><button id="next">Image suivante</button><span id="num"></span></div><div class="grid"><section class="card"><h2>Tsareena normale · référence</h2><canvas id="normal" width="400" height="300"></canvas><p class="tag" id="meta"></p></section><section class="card"><h2>Méga-Tsareena · avancement</h2><canvas id="mega" width="400" height="300"></canvas><p class="tag" id="megainfo"></p></section></div><p><a href="__MEGA__" download="Walk-Anim-avant-droite-PARTIEL.png">Télécharger la planche Walk partielle</a></p><p class="tag">Guide <a href="https://wiki.pmdo.pmdcollab.org/PMD_Sprite_Format">format PMD</a> · <a href="https://github.com/PMDCollab/SpriteCollab/tree/master/sprite/0763">Tsareena sur SpriteCollab</a> · Sprite normal : baronessfaron. Pas d’offsets ni d’ombres Méga ; planche non prête à importer.</p></main><script>const data=__DATA__,megaSrc="__MEGA__",allowed={1:[0,1,2,3]};const images={};for(const [name,a] of Object.entries(data)){images[name]=new Image();images[name].src=a.url}const mega=new Image();mega.src=megaSrc;const sel=document.querySelector('#anim'),dirs=document.querySelector('#dir');for(const name of Object.keys(data)){let o=document.createElement('option');o.value=name;o.textContent=name+(data[name].copy?' → '+data[name].copy:'');sel.append(o)}sel.value='Walk';let play=true,step=0,elapsed=0,last=performance.now();const next=document.querySelector('#next');function init(){step=0;elapsed=0;last=performance.now();dirs.disabled=data[sel.value].rows===1;document.querySelector('#meta').textContent='Référence : '+data[sel.value].durations.join(' / ')+' ticks · '+data[sel.value].rows+' direction(s)'}sel.onchange=init;dirs.onchange=()=>{step=0;elapsed=0};document.querySelector('#play').onclick=()=>{play=!play;document.querySelector('#play').textContent=play?'Pause':'Reprendre';last=performance.now()};next.onclick=()=>{play=false;document.querySelector('#play').textContent='Reprendre';step=(step+1)%data[sel.value].durations.length;elapsed=0};function draw(now){let a=data[sel.value],row=a.rows===1?0:+dirs.value;if(play){elapsed+=(now-last)*.06;while(elapsed>=a.durations[step]){elapsed-=a.durations[step];step=(step+1)%a.durations.length}}last=now;document.querySelector('#num').textContent='Image '+(step+1)+' / '+a.durations.length;const c=document.querySelector('#normal').getContext('2d');c.clearRect(0,0,400,300);c.imageSmoothingEnabled=false;let scale=Math.min(5,280/a.h,300/a.w),w=a.w*scale,h=a.h*scale;if(images[sel.value].complete&&images[sel.value].naturalWidth)c.drawImage(images[sel.value],step*a.w,row*a.h,a.w,a.h,(400-w)/2,(300-h)/2,w,h);const m=document.querySelector('#mega').getContext('2d');m.clearRect(0,0,400,300);m.imageSmoothingEnabled=false;const present=sel.value==='Walk'&&(allowed[row]||[]).includes(step);if(present&&mega.complete&&mega.naturalWidth){m.drawImage(mega,step*64,row*112,64,112,120,10,160,280);document.querySelector('#megainfo').textContent='Retouche provisoire sur le sprite normal ; les jambes sont conservées.'}else{m.fillStyle='#314539';m.font='16px system-ui';m.textAlign='center';m.fillText('Image Méga non disponible',200,145);document.querySelector('#megainfo').textContent='Case non créée ou écartée après contrôle.'}requestAnimationFrame(draw)}init();requestAnimationFrame(draw)</script></html>'''.replace('__DATA__',json.dumps(anims,ensure_ascii=False)).replace('__MEGA__',mega)
(p/'index.html').write_text(html,encoding='utf8');print('Animations',len(anims),'Mega 7/32')
